package com.careerpilot.modules.dsa.controller;
import com.careerpilot.modules.dsa.dto.DsaDtos.*;import com.careerpilot.modules.dsa.service.DsaPracticeService;import com.careerpilot.security.CurrentUser;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/dsa-practice")public class DsaPracticeController{private final DsaPracticeService service;public DsaPracticeController(DsaPracticeService service){this.service=service;}@GetMapping public Dashboard dashboard(){return service.dashboard(CurrentUser.require());}@PutMapping("/topics/{topicId}")public Dashboard update(@PathVariable String topicId,@Valid@RequestBody UpdateProgressRequest request){return service.update(CurrentUser.require(),topicId,request);}}
